    content: `<p><img src="https://pub-5dbaf337ef004f7ca4f5287b3e8b701f.r2.dev/blog/de-inceput-de-an/prima-pavea-Petra-Pavaje.jpg" alt="" loading="lazy" /></p>
<p>De Început de An! Fiecare construcție începe cu piatra de temelie. De aici se construiește mai departe. Iar fiecare etapă este importantă pentru a avea trăinicie: trebuie să folosim materiale de calitate, meșteri pricepuți, iar unii ar zice că și atitudinea cu care lucrăm asigură bunul mers al lucrării. La fiecare pas, trebuie să ne asigurăm că facem totul pentru un proiect frumos și solid.</p>
<p>Tot așa cum o construcție are la bază o primă piatră, un an începe cu o primă zi. Suntem în punctul de plecare a unui nou an. Ține de fiecare dintre noi cum ne dorim să îl clădim. Fiecare zi este o mică investiție și în fiecare zi putem face ceva care să ne facă mai prosperi, mai sănătoși și mai fericiți. Zi după zi, piatră după piatră.</p>
<p>Vă dorim să aveți un an așa cum îl visați!</p>
<h2>La mulți ani 2021!</h2>
<p>Pavaj imagine: <a href="https://petrapavaje.ro/pavaje-standard/holland/">Holland 10x20x6</a>, culori: roșu și galben. Produsul poate fi vizionat în grădinile expoziționale și la partenerii noștri.</p>`,
