    id: '3305',
    title: `Florea Pavaje devine Petra Pavaje`,
    slug: 'florea-pavaje-devine-petra-pavaje',
    excerpt: `Florea Pavaje devine Petra Pavaje, parte a companiei Florea Grup, anunțând lansarea noii sale identități.`,
    content: `<p>Florea Pavaje, parte a companiei Florea Grup, anunță lansarea noii sale identități vizuale. Începând din luna iunie, toate produsele vor fi comercializate sub numele Petra Pavaje.</p>
<p>În paralel cu investiția de peste 10 milioane de Euro în noua fabrică din Ploiești, compania a alocat resurse și campaniei de rebranding. Noul brand vine în sprijinul obiectivului de extindere la nivel național, cu o imagine proaspătă care se aliniază filosofiei companiei.</p>
<p>„Când am lansat Florea Pavaje am avut o strategie care a vizat mai ales zona Transilvaniei. Odată cu expansiunea la nivelul întregii țări, eforturile noastre s-au concentrat în a crea produse care să ne plaseze între primii producători la nivel național. Noul obiectiv a necesitat o abordare integrată, care a cuprins atât investiții în mijloace fixe, cât și în capital uman și marketing. Rebrandingul este așadar un pas important în demers. Prin acest proces dorim să comunicăm partenerilor noștri că noul nume va fi o garanție a calității, promptitudinii și eticii cu care le-am câștigat încrederea în acești trei ani. În plus, avem acum și maturitatea profesională pentru a fi competitivi pe o piața națională.” spune Marcel Florea, director general Florea Grup.</p>
<p>Noua siglă are un design modern și elegant. Logoul are în componență două culori. În primul rând este nuanța deschisă de gri, care reprezintă betonul, materia primă folosită în toate produsele. Ca și culoare secundară este roșu carmin, culoarea reprezentativă pentru compania-mamă Florea Grup, reprezentând energia, pasiunea și curajul, trei dintre valorile definitorii ale acestui grup. Elementul distinctiv al siglei este de altfel pătratul înclinat la 45% care formează litera „E”. Este singurul element cu unghiuri drepte și ascunde totodată inițialele „Fl”, sugerând legătura dintre Florea Grup și Petra Pavaje.</p>
<p>Elementul neschimbat al brandului este motto-ul: „<em>În armonie cu natura”. </em>Viziunea cu privire la un proces de producție eco-friendly este nestrămutată. Se acordă o atenție deosebită conservării resurselor naturale și proceselor de lucru cu eficiență ecologică ridicată. Mai mult, culorile și texturile produselor caută să reproducă elementele naturale, lucru cel mai bine evidențiat de noua gamă de pavaje „Inspirat din Transilvania”. Pentru a sublinia această viziune, aniversarea companiei este 5 iunie, dată care coincide cu Ziua Mediului. În 5 iunie 2017 s-au produs primele pavaje în fabrica de la Alba Iulia, iar trei ani mai târziu va demara producția în noua fabrică din Ploiești.</p>
<p>Procesul de rebranding a durat câteva luni, fiind munca combinată a specialiștilor interni, a echipei de management și a consultanților externi. Fiecare detaliu a urmărit unicitatea acestei linii de business, pornind de la auditul intern și poziționare și terminând cu refacerea identității brandului și a altor elemente de design.</p>
<p>„Prin Petra am dat viață produsului. Dacă până acum vorbeam despre pavaje, bolțari sau borduri, acum vorbim despre elemente care ne sunt alături mai mult decât prin prezența fizică. Ele ne ajută să amenajăm spațiul așa cum am visat. Este piatra transformată în ceva viu. Se spune că marii sculptori simt piatra, iar aceasta le transmite forma pe care dorește să o ia. Tot așa ne dorim ca oricine face cunoștință cu Petra Pavaje să fie inspirat să creeze grădini sau alei unice, care transformă o casă în ACASĂ. Acesta a fost firul pe care l-am urmărit când am conturat personalitatea brandului Petra: drumul de la materie primă, la element de bucurie în viața de zi cu zi.”, explică Iulia Hladiuc, manager marketing Florea Grup.</p>
<p>Florea Pavaje, acum devenit Petra Pavaje, este un brand al companiei Florea Grup, fondată de frații David și Marcel Florea în anul 1996. Experiența în producția și prelucrarea betonului, procesul integrat de fabricație și portofoliul vast de lucrări este garanția expertizei în domeniu. Noua divizie de prefabricate de beton a venit așadar ca un pas firesc în dezvoltarea companiei. Cu o istorie care a început să fie scrisă în urmă cu un sfert de secol, Florea Grup este una dintre cele mai mari companii din Transilvania, având o cifră de afaceri cumulată de peste 160 de milioane de lei în 2019 și mai mult de 500 de angajați.</p>`,
